let localSnapshot=null,localStatus=null,localPolling=null;
const hasLocalServer=window.RISKLENS_LOCAL===true;
function localPanel(){if(!hasLocalServer)return '';const s=localStatus;return panel('本地数据连接',`<div class="panel-body"><div class="definition-row"><span>连接状态</span><strong>${s?.busy?(s.stage||'刷新中')+' · '+s.done+' / '+s.total:s?'本地服务已连接':'正在连接'}</strong></div><div class="definition-row"><span>行情样本覆盖</span><strong>${s?.coverage??0} / 13 · ${esc(s?.as_of||'待获取')}</strong></div><div class="definition-row"><span>最近抓取（北京时间）</span><strong>${esc(s?.last_refresh||s?.started_at||'—')}</strong></div><div class="definition-row"><span>本地缓存</span><strong>${esc(s?.cache_path||(s?.cache_persisted===false?'仅保留在内存':'待获取'))}</strong></div>${s?.cache_warning?`<div class="notice" style="margin-top:12px">${esc(s.cache_warning)}</div>`:''}<p class="small muted" style="margin:13px 0">先重新获取历史日线并复核前一交易日，再用腾讯最新OHLC与累计成交量更新当天K线。盘中K线及信号标为未确认，回测成交只使用收盘确认样本。未复权日线尚未处理分红/拆股，公司行动可能影响信号与收益。</p><div class="actions">${button('刷新真实行情',"refreshLocalData()",true,'refresh')}${button('下载当前快照',"downloadLocalSnapshot()",false,'download')}</div>${s&&Object.keys(s.errors||{}).length?`<div class="notice" style="margin-top:14px">${esc(Object.entries(s.errors).map(([c,e])=>c+': '+e).join('；'))}</div>`:''}<p class="small muted" style="margin-top:14px">已接入：日K、累计报价量、财务披露、历史资金流、公告、ETF持仓/净值及外围代理行情。各字段以实际来源和日期为准；一致预期与独立舆情样本尚未接入。</p></div>`,'','panel-space')}
async function connectLocal(){if(!hasLocalServer)return;try{const [sr,dr]=await Promise.all([fetch('/api/status',{cache:'no-store'}),fetch('/api/snapshot',{cache:'no-store'})]);if(!sr.ok||!dr.ok)throw Error('本地服务响应异常');const status=await sr.json(),raw=await dr.json(),changed=raw.fetched_at!==localSnapshot?.fetched_at||!localSnapshot;const clean=E.validateSnapshot(raw);for(const [code,r] of Object.entries(clean.instruments)){const source=raw.instruments[code];for(const key of ['fetched_at','volume_unit','latest_quote','provider_url','skipped_rows','closed_as_of','previous_close_check','history_checked_at','financial_history','announcements','etf','nav','flows','research_errors','research_fetched_at'])r[key]=source[key];}for(const key of ['fetched_at','closed_as_of','previous_session','external','sectors'])clean[key]=raw[key];clean.data_kind='local';localSnapshot=clean;localStatus=status;if(clean.as_of&&Object.keys(clean.instruments).length&&!bt.rangeTouched){bt.end=clean.as_of;if(bt.start>bt.end)bt.start=Object.values(clean.instruments)[0].bars[0]?.date||bt.end;}if(changed||state.page==='data')render();else{renderShell();const ribbon=document.querySelector('.data-ribbon');if(ribbon)ribbon.outerHTML=banner();}if(status.busy){clearTimeout(localPolling);localPolling=setTimeout(connectLocal,2200)}}catch(e){localStatus={busy:false,coverage:0,errors:{connection:e.message}};render();toast('本地数据连接失败：'+e.message)}}
async function refreshLocalData(){if(!hasLocalServer)return;try{const r=await fetch('/api/refresh',{method:'POST',headers:{'X-RiskLens-Token':window.RISKLENS_TOKEN}});if(!r.ok)throw Error('刷新请求失败');await connectLocal();toast('正在抓取真实行情，完成后自动更新')}catch(e){toast(e.message)}}
function downloadLocalSnapshot(){if(!localSnapshot)return toast('尚无本地快照');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(localSnapshot,null,2)],{type:'application/json'}));a.href=url;a.download='RiskLens_Market_Snapshot_'+(localSnapshot.as_of||'pending')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function liveQuoteLine(code){if(mode!=='local')return '';const q=obs(code)?.latest_quote;return q?`<div class="small muted" style="margin-top:7px">${obs(code)?.completed===false?'盘中更新':'最新报价'} ${num(q.price,q.price<10?3:2)} · ${esc(q.timestamp?.replace('T',' ').replace('+08:00',''))} 北京时间</div>`:''}

function verificationPanel(){if(mode!=='local')return '';const names={verified:'已复核',repaired:'已修正',missing:'缺失'};return panel('前一交易日收盘复核',`<div class="table-wrap"><table><thead><tr><th>标的</th><th>复核交易日</th><th>结果</th><th>旧 / 新收盘</th><th>历史重取时间</th></tr></thead><tbody>${CATALOG.map(a=>{const check=obs(a.code)?.previous_close_check;return `<tr><td>${a.name}</td><td>${check?.date||'—'}</td><td>${pill(names[check?.status]||'未执行',check?.status==='missing'?'warn':'good')}</td><td class="num">${num(check?.old_close,3)} / ${num(check?.new_close,3)}</td><td>${esc(check?.checked_at?.replace('T',' ')||'—')}</td></tr>`}).join('')}</tbody></table></div><div class="panel-note">先重新获取历史K线并覆盖核对前一交易日，再读取最新报价更新当天OHLC。若前日记录缺失，不自动宣称收盘已确认。</div>`,'','panel-space')}
